pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address from, uint256 v, uint256 _decimals) public {
        _decimals = bound(_decimals, 0, 18);
        v = bound(v, 0, 1e18);

        Reverter reverter = new Reverter();

        address[] memory tos = new address[](1);
        tos[0] = address(reverter);

        bool ok;
        try c.transfer(from, address(reverter), tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
